#!/usr/bin/env bash
# Bootstraps the self-hosted stack on a local k3s cluster (via k3d) for
# testing the k3s/Kubernetes deployment path. No Cloudflare, Alchemy, or
# Convex Cloud account required.
#
# Usage:
#   bash scripts/setup-k3s.sh
#
# Requires: docker, k3d (brew install k3d), kubectl, bun, openssl.
# Idempotent-ish: re-running recreates the cluster from scratch (fast, since
# k3d clusters are cheap to tear down/rebuild) but keeps apps/web/.env secrets
# if already generated by scripts/setup-selfhosted.sh.
#
# What this does:
#   1. Creates (or reuses) a k3d cluster named "chengdu80" with ports 80/443
#      mapped to the host, so Ingress hostnames work identically to how a
#      real public DNS + Ingress would in production.
#   2. Builds the web app image and imports it into the cluster (no external
#      registry needed for this local test).
#   3. Generates/reuses a PLATFORM_INTERNAL_KEY + CONVEX_INSTANCE_SECRET,
#      stored as a Kubernetes Secret (not in git).
#   4. Deploys convex-backend, convex-dashboard, and the web app, plus an
#      Ingress with hostnames chengdu80.local / convex.chengdu80.local /
#      convex-site.chengdu80.local / convex-dashboard.chengdu80.local.
#   5. Adds those hostnames to /etc/hosts (prompts for your password via a
#      GUI dialog, since it needs root).
#   6. Generates a Convex admin key, sets CD80_DEMO_MODE/PLATFORM_INTERNAL_KEY
#      on the deployment, and pushes Convex schema/functions.

set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"

log() { printf '\n==> %s\n' "$1"; }
die() { printf 'error: %s\n' "$1" >&2; exit 1; }
rand_hex() { openssl rand -hex 32; }

# --- 1. Required tools ----------------------------------------------------
log "Checking required tools"
command -v docker >/dev/null 2>&1 || die "docker is required."
command -v k3d >/dev/null 2>&1 || die "k3d is required: brew install k3d (or see https://k3d.io)"
command -v kubectl >/dev/null 2>&1 || die "kubectl is required: brew install kubectl"
command -v openssl >/dev/null 2>&1 || die "openssl is required."
if ! command -v bun >/dev/null 2>&1; then
  export PATH="$HOME/.bun/bin:$PATH"
  command -v bun >/dev/null 2>&1 || die "bun is required: curl -fsSL https://bun.sh/install | bash"
fi
log "k3d: $(k3d version | head -1), kubectl: $(kubectl version --client -o yaml 2>/dev/null | grep gitVersion | head -1)"

# --- 2. Create (or reuse) the k3d cluster --------------------------------
log "Ensuring k3d cluster 'chengdu80' exists"
if ! k3d cluster list chengdu80 >/dev/null 2>&1; then
  k3d cluster create chengdu80 --api-port 6550 -p "80:80@loadbalancer" -p "443:443@loadbalancer" --agents 1
else
  echo "Cluster already exists; reusing it."
fi
kubectl config use-context k3d-chengdu80 >/dev/null

log "Waiting for Traefik ingress controller"
for _ in $(seq 1 30); do
  kubectl get svc -n kube-system traefik >/dev/null 2>&1 && break
  sleep 3
done
traefik_ip="$(kubectl get svc -n kube-system traefik -o jsonpath='{.spec.clusterIP}')"
[ -n "$traefik_ip" ] || die "Traefik ClusterIP not found. Check: kubectl get pods -n kube-system"
echo "Traefik ClusterIP: $traefik_ip"

# --- 3. Namespace + secrets ------------------------------------------------
log "Preparing namespace and secrets"
kubectl create namespace chengdu80 --dry-run=client -o yaml | kubectl apply -f -

if kubectl -n chengdu80 get secret chengdu80-secrets >/dev/null 2>&1; then
  platform_internal_key="$(kubectl -n chengdu80 get secret chengdu80-secrets -o jsonpath='{.data.PLATFORM_INTERNAL_KEY}' | base64 -d)"
  echo "Reusing existing chengdu80-secrets."
else
  convex_instance_secret="$(rand_hex)"
  platform_internal_key="$(rand_hex)"
  kubectl -n chengdu80 create secret generic chengdu80-secrets \
    --from-literal=CONVEX_INSTANCE_SECRET="$convex_instance_secret" \
    --from-literal=PLATFORM_INTERNAL_KEY="$platform_internal_key"
  echo "Created chengdu80-secrets (values not printed)."
fi

# --- 4. Build and import the web image ------------------------------------
log "Building the web app image"
docker build -t chengdu80-web:k3s \
  --build-arg VITE_DEMO_MODE=1 \
  --build-arg VITE_CONVEX_URL=http://convex.chengdu80.local \
  -f apps/web/Dockerfile .

log "Importing the image into the k3d cluster"
k3d image import chengdu80-web:k3s -c chengdu80 --mode direct

# --- 5. Deploy Convex backend/dashboard + Ingress -------------------------
log "Deploying Convex backend, dashboard, and Ingress"
kubectl apply -f k8s/convex.yaml
kubectl apply -f k8s/ingress.yaml

log "Waiting for convex-backend to be ready"
kubectl -n chengdu80 wait --for=condition=ready pod -l app=convex-backend --timeout=180s

# --- 6. Deploy the web app (with hostAliases pointing at Traefik) --------
log "Deploying the web app"
sed "s/\$(TRAEFIK_CLUSTER_IP)/$traefik_ip/" k8s/web.yaml | kubectl apply -f -
# kubectl wait can race the pod object not existing yet right after apply.
for _ in $(seq 1 10); do
  kubectl -n chengdu80 get pod -l app=web >/dev/null 2>&1 && break
  sleep 1
done
kubectl -n chengdu80 wait --for=condition=ready pod -l app=web --timeout=120s

# --- 7. /etc/hosts ----------------------------------------------------------
log "Ensuring /etc/hosts entries (will prompt for your password)"
if ! grep -q "chengdu80.local" /etc/hosts 2>/dev/null; then
  osascript -e 'do shell script "printf \"\n# k3s chengdu80 self-hosted test\n127.0.0.1 chengdu80.local\n127.0.0.1 convex.chengdu80.local\n127.0.0.1 convex-site.chengdu80.local\n127.0.0.1 convex-dashboard.chengdu80.local\n\" >> /etc/hosts" with administrator privileges' \
    || die "Could not update /etc/hosts. Add manually: 127.0.0.1 chengdu80.local convex.chengdu80.local convex-site.chengdu80.local convex-dashboard.chengdu80.local"
else
  echo "/etc/hosts already has chengdu80.local entries."
fi

# --- 8. Convex admin key + schema/function deploy -------------------------
log "Deploying Convex schema and functions"
admin_key="$(kubectl -n chengdu80 exec deploy/convex-backend -- ./generate_admin_key.sh | tail -1 | xargs)"
cat > packages/backend/.env.k3s <<EOF
CONVEX_SELF_HOSTED_URL=http://convex.chengdu80.local
CONVEX_SELF_HOSTED_ADMIN_KEY=${admin_key}
CD80_DEMO_MODE=1
EOF
chmod 600 packages/backend/.env.k3s

(
  cd packages/backend
  bunx --no-install convex env set CD80_DEMO_MODE 1 --env-file .env.k3s
  bunx --no-install convex env set PLATFORM_INTERNAL_KEY "${platform_internal_key}" --env-file .env.k3s
  bunx --no-install convex deploy --env-file .env.k3s -y
)

# --- 9. Done ----------------------------------------------------------------
log "k3s self-hosted stack is ready"
cat <<EOF

Web app:           http://chengdu80.local
Convex backend:    http://convex.chengdu80.local
Convex dashboard:  http://convex-dashboard.chengdu80.local

kubectl context:   k3d-chengdu80 (namespace: chengdu80)

Useful commands:
  kubectl -n chengdu80 get pods
  kubectl -n chengdu80 logs -l app=web -f
  k3d cluster stop chengdu80     # pause without deleting
  k3d cluster delete chengdu80   # full teardown
EOF
